package com.example.auth

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.sessions.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.http.*
import java.util.UUID

data class UserSession(
    val sessionId: String,
    val username: String? = null,
    val authenticated: Boolean = false,
    val csrfToken: String = UUID.randomUUID().toString()
)

fun Application.module() {
    install(Sessions) {
        cookie<UserSession>("APP_SESSION") {
            cookie.path = "/"
            cookie.httpOnly = true
            cookie.extensions["SameSite"] = "Lax"
        }
    }

    routing {
        // Pre-login endpoint that accepts a session ID parameter
        // This allows session fixation: attacker sets session ID before victim authenticates
        get("/init") {
            val requestedSessionId = call.request.queryParameters["sid"]
            val existingSession = call.sessions.get<UserSession>()

            if (requestedSessionId != null && existingSession == null) {
                // VULNERABILITY: Accepts externally-supplied session identifier
                // Does not regenerate session ID upon authentication
                call.sessions.set(UserSession(
                    sessionId = requestedSessionId,
                    username = null,
                    authenticated = false
                ))
                call.respondText("Session initialized with id: $requestedSessionId")
            } else if (existingSession != null) {
                call.respondText("Session already exists: ${existingSession.sessionId}")
            } else {
                val newId = UUID.randomUUID().toString()
                call.sessions.set(UserSession(sessionId = newId))
                call.respondText("New session: $newId")
            }
        }

        // Login endpoint - does NOT regenerate session ID after authentication
        post("/login") {
            val params = call.receiveParameters()
            val username = params["username"] ?: ""
            val password = params["password"] ?: ""

            val currentSession = call.sessions.get<UserSession>()

            if (username == "admin" && password == "secret123") {
                // BUG: Reuses existing session ID instead of generating new one
                // This completes the session fixation attack
                val authenticatedSession = UserSession(
                    sessionId = currentSession?.sessionId ?: UUID.randomUUID().toString(),
                    username = username,
                    authenticated = true
                )
                call.sessions.set(authenticatedSession)
                call.respondText("Login successful. Session: ${authenticatedSession.sessionId}")
            } else {
                call.respond(HttpStatusCode.Unauthorized, "Invalid credentials")
            }
        }

        get("/dashboard") {
            val session = call.sessions.get<UserSession>()
            if (session?.authenticated == true) {
                call.respondText("Welcome ${session.username}! Secret data here. CSRF: ${session.csrfToken}")
            } else {
                call.respond(HttpStatusCode.Forbidden, "Not authenticated")
            }
        }

        get("/health") {
            call.respondText("OK")
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}
